JIE_PAIRS = ("申酉", "午未", "辰巳", "寅卯", "子丑")
XUN_PAIRS = ("戌亥", "申酉", "午未", "辰巳", "寅卯", "子丑")


@pytest.fixture(scope="module")
def normalized():
    return normalize(BirthInput(1990, 6, 15, 8, 30, "男"), RuleProfile())


def positions(chart, sid):
    return "".join(
        BRANCHES[s["branch"] - 1]
        for s in sorted(chart["stars"], key=lambda s: s["secondary"])
        if s["id"] == sid
    )


def test_course_palaces_and_decades_from_lesson_8():
    # Course month/hour example, with a fictional male test subject.
    birth = BirthInput(1988, 3, 3, 2, 0, "男", calendar="lunar", true_solar=False)
    chart = build_chart(birth)
    assert chart["life"] == 4  # 卯
    assert chart["body"] == 6  # 巳
    assert chart["palaces"][3]["stem_name"] == "乙"
    assert chart["bureau"] == 2  # 乙卯大溪水, lesson 8 p2 纳音图
    assert [d["branch"] for d in chart["decades"][1:3]] == [4, 5]
    assert [d["age_start"] for d in chart["decades"][1:3]] == [2, 12]
    assert positions(chart, 1) == "寅"
    assert positions(chart, 7) == "寅"


@pytest.mark.parametrize("bureau,stem", [(2, 1), (3, 4), (4, 5), (5, 3), (6, 2)])
def test_all_150_purple_positions_from_course(normalized, bureau, stem):
    expected = PURPLE_DAYS[bureau].replace(" ", "")
    assert len(expected) == 30
    # month=1/hour=寅 places 命 at 子; its 五虎遁干 selects each 纳音局.
    for day, branch in enumerate(expected, 1):
        chart = build_natal(
            dict(normalized, year_stem=stem, month=1, hour_branch=3, day=day),
            "男",
            RuleProfile(),
        )
        assert chart["bureau"] == bureau
        assert positions(chart, 1) == branch, (bureau, day)


@pytest.mark.parametrize("year_branch", range(1, 13))
def test_fire_bell_and_year_stars_follow_explicit_course_positions(
    normalized, year_branch
):
    # Lesson 10 p4 (non-copy version) and lesson 11 pp4-5.
    fire_bell = ("寅戌", "卯戌", "丑卯", "酉戌")[(year_branch - 1) % 4]
    jieshen = "戌酉申未午巳辰卯寅丑子亥"[year_branch - 1]
    for hour in range(1, 13):
        chart = build_natal(
            dict(normalized, year_branch=year_branch, hour_branch=hour),
            "女",
            RuleProfile(),
        )
        assert positions(chart, 23) + positions(chart, 24) == fire_bell
        assert positions(chart, 46) == BRANCHES[year_branch - 1]
        assert positions(chart, 56) == jieshen
        assert not positions(chart, 79)  # no duplicate 解神 / 年解


@pytest.mark.parametrize("offset", range(60))
def test_course_void_pairs_keep_route_then_void_for_all_sixty_years(offset):
    for sex in ("男", "女"):
        chart = build_chart(
            BirthInput(1984 + offset, 6, 15, 12, 0, sex, true_solar=False)
        )
        assert positions(chart, 77) == JIE_PAIRS[offset % 5]
        assert positions(chart, 78) == XUN_PAIRS[offset // 10]
        for sid in (77, 78):
            pair = [s for s in chart["stars"] if s["id"] == sid]
            assert [s["secondary"] for s in pair] == [False, True]
            assert len({s["instance_id"] for s in pair}) == 2
            assert all(s in chart["palaces"][s["branch"] - 1]["stars"] for s in pair)


