@pytest.mark.parametrize("year_branch", range(1, 13))
def test_course_sequences_use_agreeing_mnemonics(normalized, year_branch):
    chart = build_natal(dict(normalized, year_branch=year_branch), "男", RuleProfile())
    palaces = chart["palaces"]
    # Lesson 11 p10 + lesson 48 p1: year branch begins 岁建.
    start = year_branch - 1
    assert [palaces[(start + i) % 12]["sequences"]["岁前"] for i in range(12)] == [
        "岁建",
        "晦气",
        "丧门",
        "贯索",
        "官符",
        "小耗",
        "大耗",
        "龙德",
        "白虎",
        "天德",
        "吊客",
        "病符",
    ]
    start = (0, 9, 6, 3)[(year_branch - 1) % 4]
    assert [palaces[(start + i) % 12]["sequences"]["将前"] for i in range(12)] == [
        "将星",
        "攀鞍",
        "岁驿",
        "息神",
        "华盖",
        "劫煞",
        "灾煞",
        "天煞",
        "指背",
        "咸池",
        "月煞",
        "亡神",
    ]


def test_lunar_year_late_zi_and_leap_month_boundaries():
    cases = [
        ("202402061200 女", "next_day", "酉戌", "辰巳"),  # after 立春, before 春节
        ("202402092330 女", "midnight", "酉戌", "辰巳"),
        ("202402092330 女", "next_day", "寅戌", "寅卯"),
    ]
    for text, boundary, fire_bell, xun in cases:
        request = parse_request(text + " 真太阳时=关", {"late_zi_rule": boundary})
        chart = build_chart(request.birth, request.profile)
        assert positions(chart, 23) + positions(chart, 24) == fire_bell
        assert positions(chart, 78) == xun
    for day, month in ((15, 2), (16, 3)):
        chart = build_chart(
            BirthInput(
                2023, 2, day, 12, 0, "女", calendar="lunar", leap=True, true_solar=False
            )
        )
        assert chart["normalized"]["month"] == month
        assert positions(chart, 46) == "卯"
        assert positions(chart, 56) == "未"


def test_old_snapshots_and_alternating_profiles_do_not_change_or_cross_contaminate():
    birth = BirthInput(1990, 6, 15, 8, 30, "男")
    legacy = build_chart(birth, RuleProfile(rule_school="wm259", geng=4))
    del legacy["profile"]["rule_school"]  # actual pre-2.4 archive shape
    saved = deepcopy(legacy)
    tables = deepcopy(TABLES)
    assert RuleProfile.from_snapshot(legacy["profile"]).rule_school == "wm259"
    assert "原版安星" in text_chart(legacy)
    for chart in (
        apply_decade(legacy, 2),
        apply_flow(legacy, year=2026),
        apply_flow(legacy, target=datetime(2026, 11, 6, 12)),
    ):
        assert chart["rules_version"] == LEGACY_RULES_VERSION
        assert [(s["id"], s["branch"]) for s in chart["stars"]] == [
            (s["id"], s["branch"]) for s in legacy["stars"]
        ]
        assert "原版安星" in text_chart(chart)
    profiles = [RuleProfile(), RuleProfile(rule_school="wm259")] * 8
    with ThreadPoolExecutor(max_workers=4) as executor:
        charts = list(executor.map(lambda p: build_chart(birth, p), profiles))
    for profile, chart in zip(profiles, charts, strict=True):
        assert chart["rules_version"] == profile.rules_version
        if profile.rule_school == "xunlongzhe":
            assert chart["rules_version"] == RULES_VERSION
            assert positions(chart, 23) == "丑"
            assert positions(chart, 46) == "午"
        else:
            assert positions(chart, 23) == "巳"
            assert positions(chart, 46) == "亥"
    assert tables == TABLES
    assert saved == legacy


def test_new_requests_default_to_course_but_explicit_custom_choices_are_preserved():
    request = parse_request("199006150830 男")
    assert request.profile.rule_school == "xunlongzhe"
    assert "校勘" in request.profile.source_label
    custom = parse_request("199006150830 男", {"geng": 4})
    assert "自定义" in custom.profile.source_label
    assert custom.profile.four_hua(7) == (3, 4, 7, 11)
    assert "自定义" not in request.profile.source_label
    with pytest.raises(ValueError, match="rule_school"):
        parse_request("199006150830 男", {"rule_school": "unknown"})
